-- 0034: Estructura del repositorio de Electricidad (96 carpetas).
-- Requiere 0033_series_y_archivos_de_formatos.sql. Ejecutar en SQL Editor.
-- Conserva documentos, permisos, nombres y carpetas existentes. No conecta Drive.
begin;
alter table public.series_formatos add column if not exists codigo text;
create unique index if not exists series_formatos_codigo_unico on public.series_formatos(codigo);
comment on column public.series_formatos.codigo is 'Código estable de la estructura del repositorio de Electricidad.';
do $seed$
declare
  fila jsonb;
  padre_id uuid;
  carpeta_id uuid;
begin
  for fila in select value from jsonb_array_elements($datos$[{"codigo":"01","nombre":"Programas analíticos","padre":null,"orden":1},{"codigo":"01.01","nombre":"Nivelación 2025","padre":"01","orden":1},{"codigo":"01.02","nombre":"Carrera 2026","padre":"01","orden":2},{"codigo":"02","nombre":"Sílabos","padre":null,"orden":2},{"codigo":"03","nombre":"POA","padre":null,"orden":3},{"codigo":"03.01","nombre":"2024","padre":"03","orden":1},{"codigo":"03.02","nombre":"2025","padre":"03","orden":2},{"codigo":"03.03","nombre":"2026","padre":"03","orden":3},{"codigo":"04","nombre":"Reconocimientos profesores","padre":null,"orden":4},{"codigo":"05","nombre":"Reconocimientos estudiantes","padre":null,"orden":5},{"codigo":"06","nombre":"Movilidad estudiantil","padre":null,"orden":6},{"codigo":"07","nombre":"Experiencia graduados","padre":null,"orden":7},{"codigo":"08","nombre":"Gestión de calidad y servicios","padre":null,"orden":8},{"codigo":"08.01","nombre":"Evidencias de evaluación y acreditación","padre":"08","orden":1},{"codigo":"08.01.01","nombre":"Pertinencia y desarrollo curricular","padre":"08.01","orden":1},{"codigo":"08.01.01.01","nombre":"Pertinencia y prospectiva","padre":"08.01.01","orden":1},{"codigo":"08.01.01.02","nombre":"Diseños curriculares","padre":"08.01.01","orden":2},{"codigo":"08.01.01.02.01","nombre":"Diseño inicial 2021","padre":"08.01.01.02","orden":1},{"codigo":"08.01.01.02.02","nombre":"Rediseño 2025","padre":"08.01.01.02","orden":2},{"codigo":"08.01.01.03","nombre":"Líneas de investigación","padre":"08.01.01","orden":3},{"codigo":"08.01.02","nombre":"Planificación y gestión de carrera","padre":"08.01","orden":2},{"codigo":"08.01.02.01","nombre":"Normativa institucional","padre":"08.01.02","orden":1},{"codigo":"08.01.02.02","nombre":"Planificación académica y administrativa","padre":"08.01.02","orden":2},{"codigo":"08.01.02.03","nombre":"Informes de gestión","padre":"08.01.02","orden":3},{"codigo":"08.01.02.03.01","nombre":"2024","padre":"08.01.02.03