.01.06","orden":3},{"codigo":"08.01.06.04","nombre":"Capacitación docente","padre":"08.01.06","orden":4},{"codigo":"08.01.06.05","nombre":"Evaluación docente","padre":"08.01.06","orden":5},{"codigo":"08.01.07","nombre":"Investigación, innovación, vinculación y transferencia","padre":"08.01","orden":7},{"codigo":"08.01.07.01","nombre":"Proyectos de investigación e innovación","padre":"08.01.07","orden":1},{"codigo":"08.01.07.02","nombre":"Proyectos de vinculación","padre":"08.01.07","orden":2},{"codigo":"08.01.07.03","nombre":"Transferencia de tecnología y conocimiento","padre":"08.01.07","orden":3},{"codigo":"08.01.08","nombre":"Prácticas preprofesionales y convenios","padre":"08.01","orden":8},{"codigo":"08.01.08.01","nombre":"Laborales","padre":"08.01.08","orden":1},{"codigo":"08.01.08.02","nombre":"Servicio comunitario","padre":"08.01.08","orden":2},{"codigo":"08.01.08.03","nombre":"Convenios gestionados","padre":"08.01.08","orden":3},{"codigo":"08.01.09","nombre":"Ambientes de aprendizaje y recursos","padre":"08.01","orden":9},{"codigo":"08.01.09.01","nombre":"Manuales de laboratorios","padre":"08.01.09","orden":1},{"codigo":"08.01.09.01.01","nombre":"Normativa Lab Electricidad","padre":"08.01.09.01","orden":1},{"codigo":"08.01.09.01.01.01","nombre":"Propuesta Braulio","padre":"08.01.09.01.01","orden":1},{"codigo":"08.01.09.02","nombre":"Ambientes de aprendizaje","padre":"08.01.09","orden":2},{"codigo":"08.01.09.03","nombre":"Herramientas pedagógicas","padre":"08.01.09","orden":3},{"codigo":"08.02","nombre":"Información, procesos y formatos estudiantiles","padre":"08","orden":2},{"codigo":"08.02.01","nombre":"Formatos de trámites académicos","padre":"08.02","orden":1},{"codigo":"08.02.02","nombre":"Prácticas preprofesionales","padre":"08.02","orden":2},{"codigo":"08.02.02.01","nombre":"Formatos anexos A–F","padre":"08.02.02","orden":1},{"codigo":"08.02.02.02","nombre":"Servicio comunitario","padre":"08.02.02","orden":2},{"codigo":"08.02.02.02.01","nombre":"Ayudantía: docencia e investigación","padre":"08.02.02.02","orden":1},{"codigo":"08.02.03","nombre":"Proceso de titulación","padre":"08.02","orden":3},{"codigo":"08.02.03.01","nombre":"Referencias IEEE","padre":"08.02.03","orden":1}]$datos$::jsonb) loop
    padre_id := null;
    if fila->>'padre' is not null then
      select id into strict padre_id from public.series_formatos where codigo = fila->>'padre';
    end if;
    carpeta_id := null;
    select id into carpeta_id from public.series_formatos where codigo = fila->>'codigo';
    if carpeta_id is null then
      -- Reutiliza una carpeta con el mismo nombre dentro del mismo padre.
      select id into carpeta_id from public.series_formatos
        where id_padre is not distinct from padre_id
        and lower(btrim(nombre)) = lower(btrim(fila->>'nombre'));
      if carpeta_id is not null then
        update public.series_formatos set codigo = fila->>'codigo'
          where id = carpeta_id and codigo is null;
        if not found then
          raise exception 'La carpeta % ya tiene otro código; revisar antes de importar.', fila->>'nombre';
        end if;
      else
        insert into public.series_formatos(nombre, id_padre, orden, codigo)
        values (fila->>'nombre', padre_id, (fila->>'orden')::smallint, fila->>'codigo');
      end if;
    end if;
  end loop;
end;
$seed$;
commit;
select codigo, nombre, id_padre from public.series_formatos where codigo is not null order by codigo;
